const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=(n=0)=>{let d=new Date();d.setDate(d.getDate()+n);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei'}).format(d)},uid=()=>crypto.randomUUID();
const seeds=[['被討厭的勇氣','岸見一郎、古賀史健','心理勵志','#9aab9c'],['原子習慣','詹姆斯・克利爾','心理勵志','#c6b490'],['人類大歷史','哈拉瑞','歷史人文','#af6d50'],['蛤蟆先生去看心理師','羅伯・狄保德','心理勵志','#819c92'],['小王子','安東尼・聖修伯里','文學小說','#5b7a86'],['設計的心理學','唐納・諾曼','藝術設計','#b99d65'],['解憂雜貨店','東野圭吾','文學小說','#61766c'],['深度工作力','卡爾・紐波特','商業管理','#8d879b'],['時間簡史','史蒂芬・霍金','科學新知','#4e6076'],['臺灣的四季','陳玉峰','歷史人文','#7b8c62'],['刻意練習','安德斯・艾瑞克森','心理勵志','#ac8279'],['看見聲音','奧利佛・薩克斯','科學新知','#8296a2']];
let db;try{db=JSON.parse(localStorage.getItem('folio-v1'))}catch{}if(!db){db={books:seeds.map((b,i)=>({id:uid(),title:b[0],author:b[1],category:b[2],color:b[3],isbn:'DEMO-'+String(i+1).padStart(5,'0'),shelf:`A${Math.floor(i/4)+1}-${String(i+1).padStart(3,'0')}`})),readers:[{id:uid(),name:'陳怡安',card:'R001',email:'yian@example.com'},{id:uid(),name:'林子軒',card:'R002',email:'zixuan@example.com'},{id:uid(),name:'王雅婷',card:'R003',email:'yating@example.com'}],loans:[]};[1,3,6].forEach((b,i)=>db.loans.push({id:uid(),book:db.books[b].id,reader:db.readers[i].id,date:day(-10-i*3),due:day(i===2?-3:4+i),returned:null,renewals:0}));}
let page='books',filter='all',query='',category='',currentPage=1;const categories=['文學小說','心理勵志','歷史人文','商業管理','藝術設計','科學新知'];const menus=[['overview','◫','總覽儀表板'],['books','▤','館藏管理'],['loans','⇄','借閱與歸還'],['readers','♧','讀者管理'],['help','⚙','使用說明']];
function save(){localStorage.setItem('folio-v1',JSON.stringify(db))}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}function activeLoan(id){return db.loans.find(l=>l.book===id&&!l.returned)}function isLate(l){return !l.returned&&l.due<day()}function navigate(p){page=p;query='';filter='all';category='';currentPage=1;render()}
function render(){save();$('#nav').innerHTML=menus.map(([id,icon,name])=>`<button class="${page===id?'active':''}" onclick="navigate('${id}')"><span>${icon}</span>${name}</button>`).join('');let title=menus.find(m=>m[0]===page)[2];$('#title').textContent=title;$('#crumb').textContent=title;$('#today').textContent=new Intl.DateTimeFormat('zh-TW',{year:'numeric',month:'long',day:'numeric',weekday:'short',timeZone:'Asia/Taipei'}).format(new Date());$('#add').hidden=['overview','help'].includes(page);$('#add').textContent=page==='books'?'＋ 新增書籍':page==='readers'?'＋ 新增讀者':'＋ 辦理借閱';$('#add').onclick=page==='books'?()=>bookForm():page==='readers'?()=>readerForm():()=>loanForm();const borrowed=db.loans.filter(l=>!l.returned).length;$('#stats').innerHTML=[['館藏總數',db.books.length,'冊館藏，持續累積知識','▤'],['在架可借',db.books.length-borrowed,'冊好書，等待下一位讀者','▥'],['借閱中',borrowed,'冊書籍，正在知識旅行','⇄'],['逾期未還',db.loans.filter(isLate).length,'筆借閱，需要您的關注','◷']].map(([t,n,s,i])=>`<article class="stat"><div class="stat-top">${t}<span class="stat-icon">${i}</span></div><strong>${n.toLocaleString()}</strong><small>${s}</small></article>`).join('');if(page==='books')books();else if(page==='loans')loans();else if(page==='readers')readers();else if(page==='overview')overview();else help()}
function bookCell(b){return `<div class="bookcell"><div class="cover" style="--cover:${/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#819c92'}">${esc(b.title)}</div><div><b>${esc(b.title)}</b><small>${esc(b.isbn)}</small></div></div>`}function status(b){let l=activeLoan(b.id);return l?`<span class="pill status ${isLate(l)?'late':'out'}">● ${isLate(l)?'逾期未還':'借閱中'}</span>`:'<span class="pill status">● 在架可借</span>'}
function books(){ $('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>館藏目錄<small>CATALOG</small></h2><span class="pill">中央館 · 全館藏</span></div><div class="tabs">${[['all','全部書籍'],['available','在架可借'],['out','借閱中']].map(([v,t])=>`<button class="${filter===v?'active':''}" onclick="filter='${v}';currentPage=1;books()">${t}</button>`).join('')}</div><div class="toolbar"><div class="search"><span>⌕</span><input id="search" aria-label="搜尋館藏" placeholder="搜尋書名、作者或 ISBN…" value="${esc(query)}" oninput="query=this.value;currentPage=1;bookRows()"></div><select aria-label="書籍分類" onchange="category=this.value;currentPage=1;bookRows()"><option value="">所有分類</option>${categories.map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select><select aria-label="排序" id="sort" onchange="bookRows()"><option value="new">登錄順序</option><option value="title">書名排序</option></select></div><div class="table-wrap"><table><thead><tr><th>書籍資訊</th><th>作者</th><th>分類</th><th>館藏位置</th><th>館藏狀態</th><th>操作</th></tr></thead><tbody id="bookRows"></tbody></table></div><div id="paging" class="pagination"></div></div>`;bookRows()}
function bookRows(){let list=db.books.filter(b=>(b.title+b.author+b.isbn).toLowerCase().includes(query.toLowerCase())&&(!category||b.category===category)&&(filter==='all'||(filter==='out'?!!activeLoan(b.id):!activeLoan(b.id))));if($('#sort').value==='title')list.sort((a,b)=>a.title.localeCompare(b.title,'zh-Hant'));let max=Math.max(1,Math.ceil(list.length/8));currentPage=Math.min(currentPage,max);$('#bookRows').innerHTML=list.slice((currentPage-1)*8,currentPage*8).map(b=>`<tr><td>${bookCell(b)}</td><td>${esc(b.author)}</td><td><span class="pill">${esc(b.category)}</span></td><td>${esc(b.shelf)}</td><td>${status(b)}</td><td><button class="row-action" onclick="${activeLoan(b.id)?`returnLoan('${activeLoan(b.id).id}')`:`loanForm('${b.id}')`}">${activeLoan(b.id)?'辦理歸還':'借閱'} ↗</button><button class="row-action" aria-label="編輯 ${esc(b.title)}" onclick="bookForm('${b.id}')">⋯</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">沒有符合條件的館藏，試試其他關鍵字。</td></tr>';$('#paging').innerHTML=`<span>共 ${list.length} 筆館藏 · 第 ${currentPage} / ${max} 頁</span><div><button ${currentPage===1?'disabled':''} onclick="currentPage--;bookRows()">←</button><button>${currentPage}</button><button ${currentPage===max?'disabled':''} onclick="currentPage++;bookRows()">→</button></div>`}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}function closeModal(){$('#modal').close()}function buttons(label='儲存'){return `<div class="form-actions"><button type="button" onclick="closeModal()">取消</button><button class="primary">${label}</button></div>`}function field(label,name,value='',required=true,type='text'){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="160"></label>`}
function bookForm(id){let b=db.books.find(b=>b.id===id)||{};modal(`<h2>${id?'編輯館藏':'新增書籍'}</h2><form id="bookForm">${field('書名','title',b.title)}${field('作者','author',b.author)}${field('ISBN／館藏編號（不可重複）','isbn',b.isbn)}<label>分類<select name="category">${categories.map(c=>`<option ${b.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('館藏位置','shelf',b.shelf)}${buttons()}</form>`);$('#bookForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());if(!data.title||!data.author||!data.isbn||!data.shelf)return toast('請填寫完整資料');if(db.books.some(x=>x.id!==id&&x.isbn===data.isbn))return toast('此館藏編號已存在');if(id)Object.assign(b,data);else db.books.unshift({...data,id:uid(),color:'#819c92'});closeModal();render();toast('館藏資料已儲存')}}
function loanForm(bookId){let available=db.books.filter(b=>!activeLoan(b.id));if(!available.length)return toast('目前沒有可借館藏');if(!db.readers.length)return toast('請先新增讀者');modal(`<h2>辦理借閱</h2><form id="loanForm"><label>選擇書籍<select name="book">${available.map(b=>`<option value="${b.id}" ${b.id===bookId?'selected':''}>${esc(b.title)} · ${esc(b.isbn)}</option>`).join('')}</select></label><label>借閱讀者<select name="reader">${db.readers.map(r=>`<option value="${r.id}">${esc(r.name)} · ${esc(r.card)}</option>`).join('')}</select></label><label>應還日期<input type="date" name="due" min="${day()}" value="${day(14)}" required></label><p>預設借期 14 天。每筆借閱可續借一次，延長 14 天。</p>${buttons('確認借出')}</form>`);$('#loanForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(activeLoan(d.book))return toast('此書已借出');db.loans.unshift({...d,id:uid(),date:day(),returned:null,renewals:0});closeModal();render();toast('借閱成功，館藏狀態已更新')}}
function returnLoan(id){let l=db.loans.find(x=>x.id===id),b=db.books.find(b=>b.id===l.book);modal(`<h2>確認歸還</h2><p>《${esc(b.title)}》歸還後將恢復為在架可借。</p><form id="returnForm">${buttons('確認歸還')}</form>`);$('#returnForm').onsubmit=e=>{e.preventDefault();l.returned=day();closeModal();render();toast('歸還完成')}}function renew(id){let l=db.loans.find(x=>x.id===id);if(isLate(l))return toast('逾期書籍請先辦理歸還');if(l.renewals)return toast('此筆借閱已續借一次');let d=new Date(l.due+'T12:00:00');d.setDate(d.getDate()+14);l.due=d.toISOString().slice(0,10);l.renewals=1;render();toast('已延長借期 14 天')}
function loans(){let list=db.loans.filter(l=>filter==='all'||(filter==='late'?isLate(l):filter==='returned'?!!l.returned:!l.returned));$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>借閱紀錄<small>CIRCULATION</small></h2></div><div class="tabs">${[['all','全部紀錄'],['active','借閱中'],['late','逾期未還'],['returned','已歸還']].map(([v,t])=>`<button class="${filter===v?'active':''}" onclick="filter='${v}';loans()">${t}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>書籍資訊</th><th>借閱讀者</th><th>借出日期</th><th>應還日期</th><th>狀態</th><th>操作</th></tr></thead><tbody>${list.map(l=>{let b=db.books.find(b=>b.id===l.book),r=db.readers.find(r=>r.id===l.reader);return `<tr><td>${bookCell(b)}</td><td>${esc(r.name)}</td><td>${l.date}</td><td>${l.due}</td><td><span class="pill status ${isLate(l)?'late':l.returned?'':'out'}">${l.returned?'已歸還':isLate(l)?'逾期未還':'借閱中'}</span></td><td>${!l.returned?`<button class="row-action" onclick="returnLoan('${l.id}')">歸還</button><button class="row-action" onclick="renew('${l.id}')" ${isLate(l)||l.renewals?'disabled':''}>${l.renewals?'已續借':'續借'}</button>`:l.returned}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">目前沒有借閱紀錄</td></tr>'}</tbody></table></div><div class="pagination">共 ${list.length} 筆借閱紀錄</div></div>`}
function readers(){$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>讀者名冊<small>PATRONS</small></h2><span class="pill">${db.readers.length} 位讀者</span></div><div class="toolbar"><div class="search"><span>⌕</span><input aria-label="搜尋讀者" placeholder="搜尋讀者姓名、借閱證號或電子信箱…" value="${esc(query)}" oninput="query=this.value;readerRows()"></div></div><div class="table-wrap"><table><thead><tr><th>讀者姓名</th><th>借閱證號</th><th>電子信箱</th><th>目前借閱</th><th>逾期</th><th>操作</th></tr></thead><tbody id="readerRows"></tbody></table></div></div>`;readerRows()}function readerRows(){$('#readerRows').innerHTML=db.readers.filter(r=>(r.name+r.card+r.email).toLowerCase().includes(query.toLowerCase())).map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.card)}</td><td>${esc(r.email)}</td><td>${db.loans.filter(l=>l.reader===r.id&&!l.returned).length} 冊</td><td>${db.loans.filter(l=>l.reader===r.id&&isLate(l)).length} 冊</td><td><button class="row-action" onclick="readerForm('${r.id}')">編輯 ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">沒有符合條件的讀者</td></tr>'}
function readerForm(id){let r=db.readers.find(r=>r.id===id)||{};modal(`<h2>${id?'編輯讀者':'新增讀者'}</h2><form id="readerForm">${field('姓名','name',r.name)}${field('借閱證號','card',r.card)}${field('電子信箱','email',r.email,false,'email')}${buttons()}</form>`);$('#readerForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));Object.keys(d).forEach(k=>d[k]=d[k].trim());if(!d.name||!d.card)return toast('請填寫姓名與借閱證號');if(db.readers.some(x=>x.id!==id&&x.card===d.card))return toast('借閱證號已存在');if(id)Object.assign(r,d);else db.readers.push({...d,id:uid()});closeModal();render();toast('讀者資料已儲存')}}
function overview(){let max=Math.max(1,...categories.map(c=>db.books.filter(b=>b.category===c).length));$('#view').innerHTML=`<div class="overview"><div class="panel"><h2>館藏分類分布</h2>${categories.map(c=>{let n=db.books.filter(b=>b.category===c).length;return `<div class="bar"><span>${c}</span><i style="width:${n/max*55}%"></i><b>${n} 冊</b></div>`}).join('')}</div><div class="panel"><h2>館務提醒</h2><div class="help"><p style="margin:25px 0">每一次借閱，都是一段新旅程。</p>目前有 <b>${db.loans.filter(isLate).length}</b> 筆逾期借閱需要處理。<br>共有 <b>${db.readers.length}</b> 位讀者加入閱讀行列。<br><br><button class="primary" onclick="navigate('loans');filter='late';loans()">查看逾期紀錄 →</button></div></div></div>`}
function help(){$('#view').innerHTML=`<div class="panel"><div class="panel-head"><h2>關於書嶼</h2></div><div class="help" style="padding:25px"><b>開始使用</b><ol><li>於館藏管理新增書籍，每個實體複本使用唯一館藏編號。</li><li>於讀者管理建立讀者與唯一借閱證號。</li><li>按下借閱，選擇讀者與應還日期；預設借期 14 天。</li><li>在借閱與歸還頁面辦理歸還或續借。未逾期書籍可續借一次。</li></ol><b>資料儲存與備份</b><p style="line-height:2">這是單一瀏覽器使用的操作版本，以 localStorage 保存資料，沒有多人同步與登入權限。清除網站資料會移除紀錄，請使用「匯出資料」定期下載 JSON 備份。初始內容為示範館藏與讀者，ISBN 欄位採示範編號。</p><br><b>功能參考</b><p style="line-height:2">功能流程參考 <a href="https://koha-community.org/manual/22.05/en/html/circulation.html" target="_blank" rel="noopener">Koha 借閱管理文件</a>，介面為書嶼原創設計。</p></div></div>`}
function exportData(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`folio-backup-${day()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('資料已匯出為 JSON 備份')}
render();